export const AVATAR_COLORS = [
  "bg-indigo-500/20 text-indigo-300",
  "bg-cyan-500/20 text-cyan-300",
  "bg-emerald-500/20 text-emerald-300",
  "bg-amber-500/20 text-amber-300",
  "bg-rose-500/20 text-rose-300",
  "bg-violet-500/20 text-violet-300",
  "bg-sky-500/20 text-sky-300",
  "bg-teal-500/20 text-teal-300",
  "bg-fuchsia-500/20 text-fuchsia-300",
  "bg-orange-500/20 text-orange-300",
];

const colorCache = {};
export function avatarColor(name = "") {
  if (!colorCache[name]) {
    const idx = [...name].reduce((a, c) => a + c.charCodeAt(0), 0) % AVATAR_COLORS.length;
    colorCache[name] = AVATAR_COLORS[idx];
  }
  return colorCache[name];
}

export function initials(name = "") {
  return (name || "?").split(/[\s_]+/).map((w) => w[0]).join("").toUpperCase().slice(0, 2) || "?";
}

export function fmtTime(date) {
  if (!date) return "";
  return new Date(date).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

export function fmtDate(date) {
  if (!date) return "";
  const d = new Date(date);
  const today = new Date();
  if (d.toDateString() === today.toDateString()) return "Today";
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);
  if (d.toDateString() === yesterday.toDateString()) return "Yesterday";
  return d.toLocaleDateString([], { month: "short", day: "numeric" });
}

export function getRoomName(room, myUsername) {
  if (room.isGroup || room.group) return room.name || "Group";
  const others = (room.participantIds || []).filter((u) => u !== myUsername);
  return others.join(", ") || myUsername;
}

export function fmtLastSeen(status, lastSeen) {
  if (status === "ONLINE") return "Online";
  if (!lastSeen) return "Offline";
  const now = new Date(), seen = new Date(lastSeen);
  const diffMin  = Math.floor((now - seen) / 60000);
  const diffHrs  = Math.floor((now - seen) / 3600000);
  const diffDays = Math.floor((now - seen) / 86400000);
  if (diffMin < 1)  return "Last seen just now";
  if (diffMin < 60) return `Last seen ${diffMin}m ago`;
  if (diffHrs < 24 && seen.toDateString() === now.toDateString())
    return `Last seen today at ${fmtTime(seen)}`;
  const yest = new Date(now); yest.setDate(yest.getDate() - 1);
  if (seen.toDateString() === yest.toDateString())
    return `Last seen yesterday at ${fmtTime(seen)}`;
  if (diffDays < 7) return `Last seen ${diffDays}d ago`;
  return `Last seen ${seen.toLocaleDateString([], { month: "short", day: "numeric" })}`;
}
